import { useParams } from 'react-router-dom'
import ProductsList from '../../components/ProductsList'
import diablo from '../../assets/images/diablo.png'
import Pratos from '../../models/Pratos'
import Banner from '../../components/Banner'

// Dados do prato Diablo
const pratoDiablo: Pratos = {
  id: 3,
  title: 'Diablo',
  nota: 10,
  description:
    'Experimente o sabor explosivo da culinária mexicana! Pratos picantes e deliciosos, com ingredientes frescos e um toque especial. Ideal para quem ama um sabor mais ardente e marcante.',
  image: diablo,
  infos: ['Mexicana', 'Picante']
}

const Diablo = () => {
  const { id } = useParams()

  return (
    <>
      <Banner />
      <h2>{pratoDiablo.title}</h2>
      <ProductsList
        pratos={[pratoDiablo]}
        title="Detalhes do Prato"
        background="gray"
      />
    </>
  )
}

export default Diablo
